// it is a no-op as well. If this loader's config is no longer the running
// one (its context has been canceled), the pulled config is discarded so a
// late result can never overwrite a newer running config.
func (d *dynamicConfigLoader) apply(loadedConfig []byte) error {
	if loadedConfig == nil {
		d.logger.Info("dynamically-loaded config was nil; no-op")
		return nil
